  RAISE NOTICE 'إجمالي: % — كمي: % — لفظي: % — قطع: %', n, nq, nv, np;
  IF n <> 118 THEN RAISE EXCEPTION 'عدد الأسئلة % لا يطابق المتوقع 118', n; END IF;
